-- 124: Original BrillaPrep WASSCE BrillaPrep IRS beta content blueprint beta questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_124_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_124_guard;
INSERT INTO _migration_124_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_011' AND NOT (q.topic_id IS 'topic_was_irs_3' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does Hijrah refer to in the Prophet’s life?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The first revelation at Hira","B. The rebuilding of the Ka’bah before prophethood","C. The migration from Makkah to Madinah","D. The farewell sermon at Arafah"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The Hijrah established a secure Muslim community in Madinah and marks the starting point used for the Islamic lunar calendar. Therefore the correct answer is C: The migration from Makkah to Madinah.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_011' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_124_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_012' AND NOT (q.topic_id IS 'topic_was_irs_3' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What was a key lesson of the brotherhood formed between the Muhajirun and Ansar?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Tribal status must determine all rights","B. Migrants should remain permanently isolated","C. Wealth should never be shared","D. Community solidarity can overcome displacement and social division"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The pairing supported displaced Makkan Muslims and strengthened mutual responsibility in the new Madinan community. Therefore the correct answer is D: Community solidarity can overcome displacement and social division.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_012' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_124_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_013' AND NOT (q.topic_id IS 'topic_was_irs_3' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why was the Treaty of Hudaybiyyah strategically important?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A period of peace created wider opportunities for contact and peaceful propagation","B. It ended every later disagreement immediately","C. It required Muslims to abandon Madinah","D. It prohibited all future pilgrimage"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Although some terms initially seemed difficult, the truce reduced conflict and allowed communication that contributed to rapid community growth. Therefore the correct answer is A: A period of peace created wider opportunities for contact and peaceful propagation.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_013' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_124_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_014' AND NOT (q.topic_id IS 'topic_was_irs_3' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What happened during the first revelation?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The Prophet was crowned king of Makkah","B. The angel Jibril commanded the Prophet to read or recite","C. The Qur’an was printed as a complete book","D. The Ka’bah was moved to Madinah"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Islamic tradition records that the first verses of Surah al-Alaq were revealed through Jibril while the Prophet was in the cave of Hira. Therefore the correct answer is B: The angel Jibril commanded the Prophet to read or recite.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_014' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_124_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_015' AND NOT (q.topic_id IS 'topic_was_irs_3' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which quality did the title al-Amin recognise in Muhammad before prophethood?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Military rank","B. Ownership of every caravan","C. Trustworthiness","D. Authority as a Roman governor"]' AND q.correct_answer IS 'C' AND q.explanation IS 'People in Makkah recognised Muhammad as trustworthy and dependable, a character quality central to his later mission and leadership. Therefore the correct answer is C: Trustworthiness.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_015' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
